"""A map folder as the editor sees it: .scmap + _scenario.lua + _save.lua + _script.lua.

Everything is kept losslessly: the scenario and save files are generic Lua tables (luadata), the .scmap a full ScMap.
`to_client()` makes the JSON document the browser edits, `apply_client()` takes it back.
"""
import array
import glob
import os
import shutil
import time

import luadata
from luadata import LuaTable
from scmap import Decal, ScMap

SAVE_HEADER = """--[[                                                                           ]]--
--[[  Generated by SC Map Studio                                                 ]]--
--[[                                                                           ]]--
--[[                                                                           ]]--
--[[  Scenario                                                                 ]]--
--[[                                                                           ]]--
"""


def _clean_floats(obj):
    """Replace NaN / inf floats in nested lists and dicts by 0.0 (in place); returns how many were replaced."""
    bad = 0
    if isinstance(obj, list):
        for i, v in enumerate(obj):
            if isinstance(v, float):
                if v != v or v in (float("inf"), float("-inf")):
                    obj[i] = 0.0
                    bad += 1
            elif isinstance(v, (list, dict)):
                bad += _clean_floats(v)
    elif isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, float):
                if v != v or v in (float("inf"), float("-inf")):
                    obj[k] = 0.0
                    bad += 1
            elif isinstance(v, (list, dict)):
                bad += _clean_floats(v)
    return bad


def _first(patterns):
    for pat in patterns:
        hits = sorted(glob.glob(pat))
        if hits:
            return hits[0]
    return None


def _read_text(path):
    with open(path, "rb") as fh:
        return fh.read().decode("latin-1")


def _empty_scenario():
    return LuaTable([
        ["next_area_id", "0"],
        ["Props", LuaTable()],
        ["Areas", LuaTable()],
        ["MasterChain", LuaTable([["_MASTERCHAIN_", LuaTable([["Markers", LuaTable()]])]])],
        ["Chains", LuaTable()],
        ["Orders", LuaTable()],
        ["next_queue_id", "1"],
        ["Platoons", LuaTable()],
        ["next_platoon_id", "1"],
        ["next_chain_id", "1"],
        ["next_marker_id", "1"],
        ["Armies", LuaTable()],
    ])


def _dump_scenario(assigns):
    out = []
    for t, v in assigns:
        if t == ["version"]:
            out.append(f"version = {v} -- Lua Version. Dont touch this\n")
        else:
            out.append(f"{'.'.join(t)} = {luadata.dumps(v, 0, 'plain')}\n")
    return "".join(out)


class MapProject:
    def __init__(self):
        self.folder = ""
        self.stem = ""
        self.scmap_path = ""
        self.scenario_path = ""
        self.save_path = ""
        self.script_path = ""
        self.scmap = None
        self.scenario_assign = []      # [(target_list, value)] of the scenario file, in order
        self.save_assign = []
        self.script = ""
        self.dirty_script = False

    # -- loading -------------------------------------------------------------------------------------------------------
    @classmethod
    def load(cls, folder):
        p = cls()
        p.folder = os.path.abspath(folder)
        sc = _first([os.path.join(glob.escape(p.folder), "*_scenario.lua")])
        if sc is None:
            raise FileNotFoundError(f"no *_scenario.lua in {folder}")
        p.scenario_path = sc
        p.stem = os.path.basename(sc)[:-len("_scenario.lua")]
        p.scenario_assign = luadata.parse_chunk(_read_text(sc))
        info = p.scenario_info()

        def sibling(key, fallback):
            if info is not None and isinstance(info.get(key), str):
                cand = os.path.join(p.folder, os.path.basename(info.get(key).replace("\\", "/")))
                if os.path.isfile(cand):
                    return cand
            return fallback

        p.scmap_path = sibling("map", _first([os.path.join(glob.escape(p.folder), "*.scmap")])
                               or os.path.join(p.folder, p.stem + ".scmap"))
        p.save_path = sibling("save", os.path.join(p.folder, p.stem + "_save.lua"))
        p.script_path = sibling("script", os.path.join(p.folder, p.stem + "_script.lua"))
        p.scmap = ScMap.read(p.scmap_path)
        if os.path.isfile(p.save_path):
            p.save_assign = luadata.parse_chunk(_read_text(p.save_path))
        else:
            p.save_assign = [(["Scenario"], _empty_scenario())]
        p.script = _read_text(p.script_path) if os.path.isfile(p.script_path) else ""
        return p

    @classmethod
    def new(cls, folder, stem, width, height, template=None):
        p = cls()
        p.folder = os.path.abspath(folder)
        p.stem = stem
        p.scmap_path = os.path.join(p.folder, stem + ".scmap")
        p.scenario_path = os.path.join(p.folder, stem + "_scenario.lua")
        p.save_path = os.path.join(p.folder, stem + "_save.lua")
        p.script_path = os.path.join(p.folder, stem + "_script.lua")
        p.scmap = template if template is not None else ScMap(width, height)
        vpath = "/maps/" + os.path.basename(p.folder).lower()
        info = LuaTable([
            ["name", stem], ["description", ""], ["preview", ""], ["map_version", 1], ["type", "skirmish"],
            ["starts", True], ["size", LuaTable([[None, width], [None, height]])],
            ["reclaim", LuaTable([[None, 0], [None, 0]])],
            ["map", f"{vpath}/{stem}.scmap"], ["save", f"{vpath}/{stem}_save.lua"],
            ["script", f"{vpath}/{stem}_script.lua"], ["norushradius", 40],
            ["Configurations", LuaTable([["standard", LuaTable([
                ["teams", LuaTable([[None, LuaTable([["name", "FFA"], ["armies", LuaTable()]])]])],
                ["customprops", LuaTable()]])]])],
        ])
        p.scenario_assign = [(["version"], 3), (["ScenarioInfo"], info)]
        p.save_assign = [(["Scenario"], _empty_scenario())]
        p.script = ("local ScenarioUtils = import('/lua/sim/ScenarioUtilities.lua')\n\n"
                    "function OnPopulate()\n    ScenarioUtils.InitializeArmies()\nend\n\n"
                    "function OnStart(self)\nend\n")
        p.dirty_script = True
        return p

    # -- tables --------------------------------------------------------------------------------------------------------
    @staticmethod
    def _find(assigns, name):
        for target, v in assigns:
            if target == [name]:
                return v
        return None

    def scenario_info(self):
        v = self._find(self.scenario_assign, "ScenarioInfo")
        return v if isinstance(v, LuaTable) else None

    def scenario_table(self):
        v = self._find(self.save_assign, "Scenario")
        return v if isinstance(v, LuaTable) else None

    # -- client document -----------------------------------------------------------------------------------------------
    def to_client(self):
        doc = self._client_doc()
        # NaN / inf cannot travel as JSON and are corrupt data anyway (some old maps have NaN prop rotations): zero them
        bad = _clean_floats(doc)
        doc["warnings"] = [f"{bad} invalid numbers (NaN/inf) in the map were replaced by 0"] if bad else []
        return doc

    def _client_doc(self):
        m = self.scmap
        scen = self.scenario_table()
        info = self.scenario_info()
        return {
            "folder": self.folder, "stem": self.stem,
            "files": {"scmap": os.path.basename(self.scmap_path), "scenario": os.path.basename(self.scenario_path),
                      "save": os.path.basename(self.save_path), "script": os.path.basename(self.script_path)},
            "minor": m.minor, "width": m.width, "height": m.height, "heightScale": m.height_scale,
            "shader": m.shader, "background": m.background, "skycube": m.skycube,
            "cubemaps": [list(c) for c in m.cubemaps],
            "lighting": m.lighting, "water": m.water, "waveGenerators": m.wave_generators,
            "carto": m.carto,
            "strata": [{"albedo": a, "scale": s} for a, s in m.strata],
            "strataNormals": [{"normal": a, "scale": s} for a, s in m.strata_normals],
            "decals": [d.to_json() for d in m.decals], "decalGroups": m.decal_groups,
            "skybox": m.skybox, "props": m.props,
            "scenarioInfo": luadata.to_py(info) if info is not None else {},
            "scenarioVersion": next((v for t, v in self.scenario_assign if t == ["version"]), 3),
            "save": luadata.to_py(scen) if scen is not None else {},
            "saveExtra": [[".".join(t), luadata.to_py(v)] for t, v in self.save_assign if t != ["Scenario"]],
            "scenarioExtra": [[".".join(t), luadata.to_py(v)] for t, v in self.scenario_assign
                              if t not in (["version"], ["ScenarioInfo"])],
            "script": self.script,
        }

    def apply_client(self, doc, blobs):
        """Update from a client document. blobs: name -> bytes (heights, maskLow, maskHigh, terrainType, ...)."""
        m = self.scmap
        m.lighting = doc["lighting"]
        m.water = doc["water"]
        m.wave_generators = doc["waveGenerators"]
        m.carto = doc["carto"]
        m.shader, m.background, m.skycube = doc["shader"], doc["background"], doc["skycube"]
        m.cubemaps = [tuple(c) for c in doc["cubemaps"]]
        m.strata = [(s["albedo"], float(s["scale"])) for s in doc["strata"]]
        m.strata_normals = [(s["normal"], float(s["scale"])) for s in doc["strataNormals"]]
        m.height_scale = doc.get("heightScale", m.height_scale)
        decals = []
        for d in doc["decals"]:
            x = Decal()
            for k in Decal.__slots__:
                setattr(x, k, d[k])
            decals.append(x)
        m.decals = decals
        m.decal_groups = doc["decalGroups"]
        m.skybox = doc.get("skybox")
        m.props = doc["props"]
        if "heights" in blobs:
            a = array.array("H")
            a.frombytes(blobs["heights"])
            if len(a) != (m.width + 1) * (m.height + 1):
                raise ValueError("heights blob has the wrong size")
            m.heights = a
        for name, attr in (("foam", "foam"), ("flatness", "flatness"), ("depthBias", "depth_bias"),
                           ("terrainType", "terrain_type")):
            if name in blobs:
                setattr(m, attr, bytearray(blobs[name]))
        for name, attr in (("maskLow", "mask_low"), ("maskHigh", "mask_high"), ("normalMap", "normal_map"),
                           ("waterMap", "water_map"), ("preview", "preview")):
            if name in blobs:
                setattr(m, attr, bytes(blobs[name]))
        info = luadata.from_py(doc["scenarioInfo"])
        assigns, replaced = [], False
        for t, v in self.scenario_assign:
            if t == ["ScenarioInfo"]:
                assigns.append((t, info))
                replaced = True
            elif t == ["version"]:
                assigns.append((t, doc.get("scenarioVersion", 3)))
            else:
                assigns.append((t, v))
        if not replaced:
            assigns.append((["ScenarioInfo"], info))
        self.scenario_assign = assigns
        scen = luadata.from_py(doc["save"])
        out, replaced = [], False
        for t, v in self.save_assign:
            if t == ["Scenario"]:
                out.append((t, scen))
                replaced = True
            else:
                out.append((t, v))
        if not replaced:
            out.insert(0, (["Scenario"], scen))
        self.save_assign = out
        if "script" in doc and doc["script"] != self.script:
            self.script = doc["script"]
            self.dirty_script = True

    # -- saving --------------------------------------------------------------------------------------------------------
    def save(self, backup=True):
        os.makedirs(self.folder, exist_ok=True)
        written = []
        targets = [self.scmap_path, self.scenario_path, self.save_path]
        if self.dirty_script:
            targets.append(self.script_path)
        if backup:
            stamp = time.strftime("%Y%m%d_%H%M%S")
            bdir = os.path.join(self.folder, ".editor_backup", stamp)
            for t in targets:
                if os.path.isfile(t):
                    os.makedirs(bdir, exist_ok=True)
                    shutil.copy2(t, os.path.join(bdir, os.path.basename(t)))
        self.scmap.write(self.scmap_path)
        written.append(self.scmap_path)
        with open(self.scenario_path, "w", encoding="latin-1", newline="\n") as fh:
            fh.write(_dump_scenario(self.scenario_assign))
        written.append(self.scenario_path)
        with open(self.save_path, "w", encoding="latin-1", newline="\n") as fh:
            fh.write(SAVE_HEADER + luadata.dump_chunk([(".".join(t), v) for t, v in self.save_assign]))
        written.append(self.save_path)
        if self.dirty_script:
            with open(self.script_path, "w", encoding="latin-1", newline="\n") as fh:
                fh.write(self.script)
            written.append(self.script_path)
            self.dirty_script = False
        return written
